function escapeHtml(str){if(typeof str!=='string')return'';return str.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

function extractSnippet(html,line,col,ctx){
var lines=html.split('\n');var s='';var st=Math.max(0,line-ctx-1);var en=Math.min(lines.length,line+ctx);
for(var i=st;i<en;i++){var ln=i+1;var p=ln===line?'&gt;':'  ';var t=escapeHtml(lines[i]||'');s+=p+' '+ln+'| '+t+'\n';if(ln===line&&col){var ptr='';for(var q=0;q<t.length&&q<col-1;q++)ptr+=t[q]==='\t'?'\t':' ';ptr+='^'.repeat(Math.min(t.length-col+1||1,20));s+='     '+ptr+'\n';}}
return s;}

function calcScore(c,e,w,i){var sc=100;sc-=Math.min(60,c*10);sc-=Math.min(40,e*5);sc-=Math.min(20,w*2);return Math.max(0,sc);}
function gradeLabel(sc){if(sc>=95)return'Excellent';if(sc>=85)return'Very Good';if(sc>=70)return'Good';if(sc>=50)return'Needs Improvement';return'Poor';}
function gradeColor(sc){return sc>=95?'#16a34a':sc>=85?'#2563eb':sc>=70?'#d97706':sc>=50?'#ea580c':'#dc2626';}
function gradeBg(sc){return sc>=95?'#f0fdf4':sc>=85?'#eff6ff':sc>=70?'#fffbeb':sc>=50?'#fff7ed':'#fef2f2';}

function renderScoreCard(label,sc,sub){var g=gradeLabel(sc),c=gradeColor(sc),b=gradeBg(sc);return'<div class="score-card" style="background:'+b+';border:1px solid '+(sc>=85?'#bbf7d0':sc>=70?'#fde68a':sc>=50?'#fed7aa':'#fecaca')+';border-radius:10px;padding:14px;text-align:center"><div class="score-label" style="font-size:10px;font-weight:700;color:#64748b;text-transform:uppercase;letter-spacing:.5px;margin-bottom:2px">'+label+'</div><div class="score-value" style="font-size:28px;font-weight:800;color:'+c+';font-family:\'JetBrains Mono\',monospace;line-height:1.2">'+sc+'<span style="font-size:14px;font-weight:600;color:#94a3b8">/100</span></div><div class="score-grade" style="font-size:11px;font-weight:700;color:'+c+';margin-top:1px">'+g+'</div>'+(sub?'<div class="score-bar" style="margin-top:8px;height:4px;background:#e2e8f0;border-radius:4px;overflow:hidden"><div style="width:'+sc+'%;height:100%;background:'+c+';border-radius:4px;transition:width .6s ease"></div></div>':'')+'</div>';}

function genCurrent(code,el,av,an){
if(code==='MISSING_ALT')return'<span class="fix-current-code">&lt;img src=&quot;...&quot;&gt;</span>';
if(code==='EMPTY_ALT')return'<span class="fix-current-code">&lt;img alt=&quot;&quot;&gt;</span>';
if(code==='DUPLICATE_ID')return'<span class="fix-current-code">&lt;'+escapeHtml(el)+' id=&quot;'+escapeHtml(av)+'&quot;&gt;</span>';
if(code==='DUPLICATE_ATTR')return'<span class="fix-current-code">&lt;'+escapeHtml(el)+' '+escapeHtml(av)+'=&quot;...&quot; '+escapeHtml(av)+'=&quot;...&quot;&gt;</span>';
if(code==='BROKEN_LABEL')return'<span class="fix-current-code">&lt;label for=&quot;'+escapeHtml(av)+'&quot;&gt;</span>';
if(code==='MISSING_BUTTON_TYPE')return'<span class="fix-current-code">&lt;button&gt;Submit&lt;/button&gt;</span>';
if(code==='MISSING_LANG')return'<span class="fix-current-code">&lt;html&gt;</span>';
if(code==='DEPRECATED_TAG')return'<span class="fix-current-code">&lt;'+escapeHtml(el)+'&gt;</span>';
if(code==='UNCLOSED_TAG')return'<span class="fix-current-code">&lt;'+escapeHtml(el)+'&gt;...&lt;/'+escapeHtml(el)+'&gt; (missing)</span>';
if(code==='UNEXPECTED_CLOSE')return'<span class="fix-current-code">&lt;/'+escapeHtml(el)+'&gt;</span>';
if(code==='INVALID_NESTING')return'<span class="fix-current-code">...&lt;'+escapeHtml(el)+'&gt; inside &lt;'+escapeHtml(an)+'&gt;</span>';
if(code==='HEADING_SKIP')return'<span class="fix-current-code">&lt;'+escapeHtml(el)+'&gt; (heading level skipped)</span>';
if(code==='TABINDEX_MISUSE')return'<span class="fix-current-code">&lt;'+escapeHtml(el)+' tabindex=&quot;'+escapeHtml(av)+'&quot;&gt;</span>';
if(code==='UNKNOWN_ATTR')return'<span class="fix-current-code">&lt;'+escapeHtml(el)+' '+escapeHtml(av)+'=&quot;...&quot;&gt;</span>';
if(code==='UNKNOWN_EVENT')return'<span class="fix-current-code">&lt;'+escapeHtml(el)+' '+escapeHtml(av)+'=&quot;...&quot;&gt;</span>';
if(code==='MULTIPLE_H1')return'<span class="fix-current-code">&lt;h1&gt;...&lt;/h1&gt; (multiple)</span>';
if(code==='BROKEN_ARIA_LABELLEDBY')return'<span class="fix-current-code">aria-labelledby=&quot;'+escapeHtml(av)+'&quot; (missing target)</span>';
if(code==='BROKEN_ARIA_DESCRIBEDBY')return'<span class="fix-current-code">aria-describedby=&quot;'+escapeHtml(av)+'&quot; (missing target)</span>';
if(code==='IMPLICIT_CLOSE')return'<span class="fix-current-code">&lt;'+escapeHtml(el)+'&gt; implicitly closed</span>';
if(code==='MISSING_TD_CLOSE')return'<span class="fix-current-code">&lt;'+escapeHtml(el)+'&gt; (missing closing tag)</span>';
if(code==='MISSING_TH_CLOSE')return'<span class="fix-current-code">&lt;'+escapeHtml(el)+'&gt; (missing closing tag)</span>';
if(code==='MISSING_TR_CLOSE')return'<span class="fix-current-code">&lt;'+escapeHtml(el)+'&gt; (missing closing tag)</span>';
if(code==='UNLABELED_INPUT')return'<span class="fix-current-code">&lt;input id=&quot;'+escapeHtml(av)+'&quot;&gt;</span>';
if(code==='LANG_MISMATCH')return'<span class="fix-current-code">&lt;html lang=&quot;'+escapeHtml(av)+'&quot;&gt;</span>';
if(code==='MISSING_META_DESC')return'<span class="fix-current-code">&lt;meta&gt; (missing description)</span>';
if(code==='MISSING_CANONICAL')return'<span class="fix-current-code">&lt;link&gt; (missing canonical)</span>';
return'';}
function genSuggested(code,el,av,an){
if(code==='MISSING_ALT')return'<span class="fix-suggest-code">&lt;img src=&quot;...&quot; alt=&quot;Description&quot;&gt;</span>';
if(code==='EMPTY_ALT')return'<span class="fix-suggest-code">&lt;img alt=&quot;Description of image&quot;&gt;</span>';
if(code==='DUPLICATE_ID')return'<span class="fix-suggest-code">&lt;'+escapeHtml(el)+' id=&quot;'+escapeHtml(el)+'_1&quot;&gt;</span>';
if(code==='DUPLICATE_ATTR')return'<span class="fix-suggest-code">Remove duplicate '+escapeHtml(av)+'</span>';
if(code==='BROKEN_LABEL')return'<span class="fix-suggest-code">&lt;input id=&quot;'+escapeHtml(av)+'&quot;&gt;</span>';
if(code==='MISSING_BUTTON_TYPE')return'<span class="fix-suggest-code">&lt;button type=&quot;button&quot;&gt;Submit&lt;/button&gt;</span>';
if(code==='MISSING_LANG')return'<span class="fix-suggest-code">&lt;html lang=&quot;en&quot;&gt;</span>';
if(code==='DEPRECATED_TAG')return'<span class="fix-suggest-code">Replace &lt;'+escapeHtml(el)+'&gt; with modern HTML/CSS.</span>';
if(code==='UNCLOSED_TAG')return'<span class="fix-suggest-code">&lt;/'+escapeHtml(el)+'&gt; (add closing tag)</span>';
if(code==='UNEXPECTED_CLOSE')return'<span class="fix-suggest-code">Remove extra &lt;/'+escapeHtml(el)+'&gt;</span>';
if(code==='INVALID_NESTING')return'<span class="fix-suggest-code">Move &lt;'+escapeHtml(el)+'&gt; outside &lt;'+escapeHtml(an)+'&gt;</span>';
if(code==='HEADING_SKIP')return'<span class="fix-suggest-code">Use h'+(parseInt(el&&el[1]||'3')-1)+' instead of '+escapeHtml(el)+'</span>';
if(code==='TABINDEX_MISUSE')return'<span class="fix-suggest-code">Use tabindex=&quot;0&quot; or tabindex=&quot;-1&quot;</span>';
if(code==='UNKNOWN_ATTR')return'<span class="fix-suggest-code">Use data-'+escapeHtml(av)+'=&quot;...&quot; instead</span>';
if(code==='UNKNOWN_EVENT')return'<span class="fix-suggest-code">Remove or fix the event handler</span>';
if(code==='MULTIPLE_H1')return'<span class="fix-suggest-code">Consolidate into a single &lt;h1&gt;</span>';
if(code==='BROKEN_ARIA_LABELLEDBY')return'<span class="fix-suggest-code">Add id=&quot;'+escapeHtml(av)+'&quot; to the target element</span>';
if(code==='BROKEN_ARIA_DESCRIBEDBY')return'<span class="fix-suggest-code">Add id=&quot;'+escapeHtml(av)+'&quot; to the target element</span>';
if(code==='IMPLICIT_CLOSE')return'<span class="fix-suggest-code">Explicitly close &lt;'+escapeHtml(el)+'&gt; before &lt;'+escapeHtml(an)+'&gt;</span>';
if(code==='MISSING_TD_CLOSE')return'<span class="fix-suggest-code">&lt;/td&gt; (add missing closing tag)</span>';
if(code==='MISSING_TH_CLOSE')return'<span class="fix-suggest-code">&lt;/th&gt; (add missing closing tag)</span>';
if(code==='MISSING_TR_CLOSE')return'<span class="fix-suggest-code">&lt;/tr&gt; (add missing closing tag)</span>';
if(code==='UNLABELED_INPUT')return'<span class="fix-suggest-code">&lt;label for=&quot;'+escapeHtml(av)+'&quot;&gt;Label text&lt;/label&gt;</span>';
if(code==='LANG_MISMATCH')return'<span class="fix-suggest-code">Update lang attribute to match content language</span>';
if(code==='MISSING_META_DESC')return'<span class="fix-suggest-code">&lt;meta name=&quot;description&quot; content=&quot;Describe this page&quot;&gt;</span>';
if(code==='MISSING_CANONICAL')return'<span class="fix-suggest-code">&lt;link rel=&quot;canonical&quot; href=&quot;https://example.com/page&quot;&gt;</span>';
return'';}
