function isWS(ch){return ch===' '||ch==='\t'||ch==='\n'||ch==='\r';}
function isAlpha(ch){return(ch>='a'&&ch<='z')||(ch>='A'&&ch<='Z');}
function isNameChar(ch){return isAlpha(ch)||(ch>='0'&&ch<='9')||ch==='_'||ch==='-'||ch===':';}
function addIss(type,code,msg,sug,l,c,el,det,cat,fix,sev){var iss={type:type,code:code,message:msg,suggestion:sug,line:l,col:c,element:el};if(det)iss.detail=det;if(cat)iss.category=cat;if(fix)iss.fix=fix;iss.severity=sev||type;issues.push(iss);}
function advance(){if(pos>=len)return;var ch=html[pos];pos++;if(ch==='\r'){line++;col=1;if(pos<len&&html[pos]==='\n')pos++;}else if(ch==='\n'){line++;col=1;}else col++;}
function skipWS(){while(pos<len&&isWS(html[pos]))advance();}
function parseTagName(){var n='';while(pos<len&&(isAlpha(html[pos])||(n.length>0&&html[pos]>='0'&&html[pos]<='9'))){n+=html[pos];advance();}return n.toLowerCase();}
function parseAttrName(){if(pos>=len)return'';var ch=html[pos];if(!(isAlpha(ch)||ch==='_'||ch===':'))return'';var n='';n+=html[pos];advance();while(pos<len&&isNameChar(html[pos])){n+=html[pos];advance();}return n;}
function parseAttrValue(){var v='';if(pos>=len)return v;var q=html[pos];if(q==='"'||q==="'"){advance();while(pos<len&&html[pos]!==q){v+=html[pos];advance();}if(pos<len)advance();}else{while(pos<len&&!isWS(html[pos])&&html[pos]!=='>'&&html[pos]!=='/'){v+=html[pos];advance();}}return v;}
function isHeading(t){return t.length===2&&t[0]==='h'&&t[1]>='1'&&t[1]<='6';}
