if(result.duplicateIds>0)recList.push({text:'Replace duplicate IDs to ensure valid CSS, JavaScript, and accessibility targeting.',impact:'High'});
if(result.a11yWarnings>0)recList.push({text:'Add alt text to images and fix label/ARIA associations for screen reader support.',impact:'High'});
if(!result.hasTitle)recList.push({text:'Add a <title> tag for SEO and browser tab display.',impact:'High'});if(!result.hasMetaDesc)recList.push({text:'Add a meta description for search engine snippets.',impact:'High'});if(!result.hasViewport)recList.push({text:'Add a viewport meta tag for responsive design and SEO.',impact:'High'});if(!result.hasCharset)recList.push({text:'Add a charset meta tag for proper text rendering.',impact:'Medium'});if(!result.hasLang)recList.push({text:'Add a lang attribute to <html> for accessibility and SEO.',impact:'High'});if(!result.hasCanonical)recList.push({text:'Add a canonical URL to prevent duplicate content issues.',impact:'Medium'});if(result.multipleH1)recList.push({text:'Use only a single <h1> per page for better document outline and SEO.',impact:'Medium'});
var hasNesting=false;for(var ni=0;ni<result.issues.length;ni++){if(result.issues[ni].code==='INVALID_NESTING')hasNesting=true;}
if(hasNesting)recList.push({text:'Fix invalid nesting to ensure consistent rendering across all browsers.',impact:'Medium'});
var hasUnclosed=false;for(var ui=0;ui<result.issues.length;ui++){if(result.issues[ui].code==='UNCLOSED_TAG')hasUnclosed=true;}
if(hasUnclosed)recList.push({text:'Close all unclosed tags to prevent unexpected layout and styling issues.',impact:'High'});
if(result.warningCount>0)recList.push({text:'Address warnings to improve code quality, maintainability, and best practices.',impact:'Medium'});
var hasDeprecated=false;for(var di=0;di<result.issues.length;di++){if(result.issues[di].code==='DEPRECATED_TAG')hasDeprecated=true;}
