for(var ac=0;ac<aIssues.length;ac++){var cd=aIssues[ac].code;if(cd==='MISSING_ALT')aC.missingAlt++;else if(cd==='BROKEN_LABEL'||cd==='BROKEN_ARIA_LABELLEDBY'||cd==='BROKEN_ARIA_DESCRIBEDBY')aC.badAria++;else if(cd==='MISSING_BUTTON_TYPE')aC.missButtonType++;else if(cd==='HEADING_SKIP')aC.headingSkip++;else if(cd==='TABINDEX_MISUSE')aC.tabMisuse++;}
