function getExportText(r){
var lines=[];function l(t){lines.push(t);}
l('========================================');l('         HTML VALIDATOR REPORT');l('========================================');l('');l('Generated: '+new Date().toLocaleString('en-US',{year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'}));l('Tool: GoToolly HTML Validator');l('URL: https://gotoolly.com/tools/html-validator');l('');
var ov=calcScore(r.criticalCount||0,r.errorCount||0,r.warningCount||0,r.infoCount||0);
  l('--- VALIDATION SUMMARY ---');l('Overall Score: '+ov+'/100 - '+gradeLabel(ov));l('Total Tags: '+(r.tagCount||0));l('Valid Elements: '+(r.validTags||0));l('Critical: '+(r.criticalCount||0));l('Errors: '+(r.errorCount||0));l('Warnings: '+(r.warningCount||0));l('Info: '+(r.infoCount||0));l('Processing Time: '+(r.time<1?'<1 ms':Math.round(r.time)+' ms'));l('');
l('--- QUALITY DASHBOARD ---');l('Structure: '+calcScore(r.issues?r.issues.filter(function(i){return i.category==='structure'&&(i.severity==='error'||i.severity==='critical');}).length:0,0,0,0)+'/100');l('Accessibility: '+(r.a11yWarnings===0?100:Math.max(0,100-Math.min(50,r.a11yWarnings*12)))+'/100');l('SEO: '+(r.seoScore||100)+'/100');l('Semantics: 100/100');l('Compatibility: 100/100');l('');
l('--- STATISTICS ---');l('Elements: '+(r.totalElements||0));l('Images: '+(r.imageCount||0));l('Forms: '+(r.formCount||0));l('Tables: '+(r.tableCount||0));l('Unique IDs: '+(r.uniqueIds||0));l('Duplicate IDs: '+(r.duplicateIds||0));l('DOM Depth: '+(r.stats?r.stats.depth||0:0));l('Max Nesting: '+(r.stats?r.stats.maxNesting||0:0));l('Comments: '+(r.stats?r.stats.comments||0:0));l('Scripts: '+(r.stats?r.stats.scripts||0:0));l('Styles: '+(r.stats?r.stats.styles||0:0));l('Meta Tags: '+(r.stats?r.stats.meta||0:0));l('Links: '+(r.stats?r.stats.links||0:0));l('Buttons: '+(r.stats?r.stats.buttons||0:0));l('Inputs: '+(r.stats?r.stats.inputs||0:0));l('Lists: '+(r.stats?r.stats.lists||0:0));l('');
l('--- VALIDATION STANDARDS ---');l('HTML5 - W3C Recommendation');l('WHATWG HTML Living Standard');l('WCAG 2.2 - Web Content Accessibility');l('ARIA 1.2 - Accessible Rich Internet Applications');l('SEO Best Practices');l('');
l('--- ISSUES ---');(r.issues||[]).forEach(function(i){var sev=(i.severity||i.type).toUpperCase();var loc=i.line?' (Line '+i.line+(i.col?', Col '+i.col:'')+')':'';l('['+sev+'] '+i.message+loc);if(i.detail)l('  -> '+i.detail);if(i.suggestion)l('  -> '+i.suggestion);l('');});
l('--- RECOMMENDATIONS ---');if(r.criticalCount>0)l('[Critical] Fix all critical errors preventing proper rendering of the page.');if(r.duplicateIds>0)l('[High] Replace duplicate IDs for valid CSS/JS/accessibility.');if(r.a11yWarnings>0)l('[High] Add alt text to images and fix label/ARIA references.');if(r.warningCount>0)l('[Medium] Address all warnings to improve code quality.');l('');
l('--- END OF REPORT ---');l('Generated by GoToolly.com');return lines.join('\n');}

function exportCopy(){if(!state.results)return;var t=getExportText(state.results);if(navigator.clipboard){navigator.clipboard.writeText(t.trim()).then(function(){showToast('Copied to clipboard!','success');});}else{fallbackCopy(t.trim());}}
function exportTxt(){if(!state.results)return;var t=getExportText(state.results);downloadFile('html-validator-report.txt',t,'text/plain');showToast('Downloaded TXT report','success');}
function exportMd(){if(!state.results)return;var r=state.results;var ov=calcScore(r.criticalCount||0,r.errorCount||0,r.warningCount||0,r.infoCount||0);var md='# HTML Validator Report\n\n**Generated:** '+new Date().toLocaleString('en-US',{year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'})+'\n\n## Validation Summary\n\n| Metric | Value |\n|--------|-------|\n| Overall Score | '+ov+'/100 ('+gradeLabel(ov)+') |\n| Total Tags | '+(r.tagCount||0)+' |\n| Valid Elements | '+(r.validTags||0)+' |\n| Critical | '+(r.criticalCount||0)+' |\n| Errors | '+(r.errorCount||0)+' |\n| Warnings | '+(r.warningCount||0)+' |\n| Info | '+(r.infoCount||0)+' |\n| Processing Time | '+(r.time<1?'<1 ms':Math.round(r.time)+' ms')+' |\n\n## Quality Dashboard\n\n| Category | Score |\n|----------|-------|\n| Structure | '+calcScore(r.issues?r.issues.filter(function(i){return i.category==='structure'&&(i.severity==='error'||i.severity==='critical');}).length:0,0,0,0)+'/100 |\n| Accessibility | '+(r.a11yWarnings===0?100:Math.max(0,100-Math.min(50,r.a11yWarnings*12)))+'/100 |\n| SEO | '+(r.seoScore||100)+'/100 |\n\n## Statistics\n\n| Metric | Value |\n|--------|-------|\n| Elements | '+(r.totalElements||0)+' |\n| Images | '+(r.imageCount||0)+' |\n| Forms | '+(r.formCount||0)+' |\n| Tables | '+(r.tableCount||0)+' |\n| Unique IDs | '+(r.uniqueIds||0)+' |\n| Duplicate IDs | '+(r.duplicateIds||0)+' |\n| DOM Depth | '+(r.stats?r.stats.depth||0:0)+' |\n| Max Nesting | '+(r.stats?r.stats.maxNesting||0:0)+' |\n| Scripts | '+(r.stats?r.stats.scripts||0:0)+' |\n| Styles | '+(r.stats?r.stats.styles||0:0)+' |\n| Meta Tags | '+(r.stats?r.stats.meta||0:0)+' |\n| Links | '+(r.stats?r.stats.links||0:0)+' |\n| Buttons | '+(r.stats?r.stats.buttons||0:0)+' |\n| Inputs | '+(r.stats?r.stats.inputs||0:0)+' |\n\n## Validation Standards\n\n- HTML5 (W3C Recommendation)\n- WHATWG HTML Living Standard\n- WCAG 2.2 (Web Content Accessibility)\n- ARIA 1.2\n- SEO Best Practices\n\n## Issues\n\n';(r.issues||[]).forEach(function(i){var sev=i.severity||i.type;var loc=i.line?'(Line '+i.line+(i.col?', Col '+i.col:'')+')':'';md+='- **['+sev.toUpperCase()+']** '+i.message+' '+loc+'\n';if(i.detail)md+='  - *'+i.detail+'*\n';});md+='\n## Recommendations\n\n';if(r.criticalCount>0)md+='- **Critical:** Fix all critical errors\n';if(r.duplicateIds>0)md+='- **High:** Replace duplicate IDs\n';if(r.a11yWarnings>0)md+='- **High:** Add alt text and fix label references\n';md+='\n---\n*Report generated by [GoToolly HTML Validator](https://gotoolly.com/tools/html-validator)*\n';downloadFile('html-validator-report.md',md,'text/markdown');showToast('Downloaded Markdown report','success');}
function exportJson(){if(!state.results)return;var r=state.results;var ov=calcScore(r.criticalCount||0,r.errorCount||0,r.warningCount||0,r.infoCount||0);var obj={reportType:'HTML Validation Report',generatedAt:new Date().toISOString(),tool:'GoToolly HTML Validator',url:'https://gotoolly.com/tools/html-validator',overallScore:ov,qualityRating:gradeLabel(ov),summary:{totalTags:r.tagCount,validElements:r.validTags,critical:r.criticalCount,errors:r.errorCount,warnings:r.warningCount,info:r.infoCount,processingTimeMs:Math.round(r.time)},qualityScores:{overall:ov,accessibility:r.a11yWarnings===0?100:Math.max(0,100-Math.min(50,r.a11yWarnings*12)),seo:r.seoScore||100},statistics:{totalElements:r.totalElements,uniqueIds:r.uniqueIds,duplicateIds:r.duplicateIds,images:r.imageCount,forms:r.formCount,tables:r.tableCount,scripts:r.stats?r.stats.scripts:0,styles:r.stats?r.stats.styles:0,meta:r.stats?r.stats.meta:0,links:r.stats?r.stats.links:0,buttons:r.stats?r.stats.buttons:0,inputs:r.stats?r.stats.inputs:0,lists:r.stats?r.stats.lists:0,headers:r.stats?r.stats.headers:0,comments:r.stats?r.stats.comments:0,depth:r.stats?r.stats.depth:0,maxNesting:r.stats?r.stats.maxNesting:0,svg:r.stats?r.stats.svg:0,customElements:r.stats?r.stats.custom:0},validationStandards:['HTML5 (W3C Recommendation)','WHATWG HTML Living Standard','WCAG 2.2','ARIA 1.2','SEO Best Practices'],issues:(r.issues||[]).map(function(i){var o={type:i.type,code:i.code,message:i.message,severity:i.severity||i.type,element:i.element,line:i.line,col:i.col,category:i.category};if(i.detail)o.detail=i.detail;if(i.fix)o.fix=i.fix;return o;}),recommendations:[]};if(r.criticalCount>0)obj.recommendations.push('Fix all critical errors');if(r.duplicateIds>0)obj.recommendations.push('Replace duplicate IDs');if(r.a11yWarnings>0)obj.recommendations.push('Add alt text and fix label associations');var json=JSON.stringify(obj,null,2);downloadFile('html-validator-report.json',json,'application/json');showToast('Downloaded JSON report','success');}
