function downloadFile(fn,cont,mime){var blob=new Blob([cont],{type:mime});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download=fn;document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);}
function fallbackCopy(text){var ta=document.createElement('textarea');ta.style.cssText='position:fixed;opacity:0';ta.value=text;document.body.appendChild(ta);ta.select();try{document.execCommand('copy');showToast('Copied!','success');}catch(e){showToast('Failed to copy','error');}document.body.removeChild(ta);}

function renderComparison(){if(!elements.comparisonSelect||!elements.comparisonTable)return;var avail=state.history.filter(function(item){return!state.results||item.inputText!==state.results.inputText;});if(avail.length===0||state.history.length<=1){if(elements.comparisonSection)elements.comparisonSection.style.display='none';return;}if(elements.comparisonSection)elements.comparisonSection.style.display='block';var h='<option value="">Select previous...</option>';avail.forEach(function(item,i){var idx=state.history.indexOf(item);h+='<option value="'+idx+'">'+item.inputText+' ('+item.tagCount+' tags)</option>';});elements.comparisonSelect.innerHTML=h;}
function onComparisonChange(){var idx=parseInt(elements.comparisonSelect.value);if(isNaN(idx)||!state.history[idx]||!state.results){elements.comparisonTable.innerHTML='';return;}var prev=state.history[idx];var curr=state.results;var metrics=[{label:'Tags',curr:curr.tagCount,prev:prev.tagCount},{label:'Errors+Critical',curr:(curr.errorCount||0)+(curr.criticalCount||0),prev:(prev.errorCount||0)+(prev.criticalCount||0)},{label:'Warnings',curr:curr.warningCount,prev:prev.warningCount},{label:'Valid Tags',curr:curr.validTags,prev:prev.validTags},{label:'Elements',curr:curr.totalElements,prev:prev.totalElements},{label:'Unique IDs',curr:curr.uniqueIds,prev:prev.uniqueIds},{label:'Duplicate IDs',curr:curr.duplicateIds,prev:prev.duplicateIds}];var h='<table class="comparison-table"><thead><tr><th>Metric</th><th>Current</th><th>Previous</th><th>Change</th></tr></thead><tbody>';metrics.forEach(function(m){var diff=typeof m.curr==='number'?m.curr-m.prev:0;var arrow=diff>0?'<span class="comp-up">+'+diff+'</span>':diff<0?'<span class="comp-down">'+diff+'</span>':'<span class="comp-same">0</span>';h+='<tr><td>'+m.label+'</td><td>'+m.curr+'</td><td>'+m.prev+'</td><td>'+arrow+'</td></tr>';});h+='</tbody></table>';elements.comparisonTable.innerHTML=h;}
function renderHistory(){if(!elements.historyList)return;if(state.history.length<=1){if(elements.historySection)elements.historySection.style.display='none';return;}if(elements.historySection)elements.historySection.style.display='block';var h='';for(var i=state.history.length-1;i>=0;i--){var item=state.history[i];var active=state.results&&item.inputText===state.results.inputText?' style="border-color:var(--color-primary);background:rgba(37,99,235,0.05)"':'';h+='<div class="history-item"'+active+'><div class="history-meta"><span class="history-time">Validated</span><span class="history-size">'+item.tagCount+' tags</span></div><div class="history-lines">'+(item.criticalCount?item.criticalCount+' critical, ':'')+(item.errorCount||0)+' errors, '+(item.warningCount||0)+' warnings</div></div>';}elements.historyList.innerHTML=h;}
function copyFixCode(fixId){var el=document.getElementById(fixId);if(!el)return;var codeEl=el.querySelector('.fix-suggest-code');if(!codeEl)codeEl=el.querySelector('.fix-current-code');if(!codeEl)codeEl=el.querySelector('.fix-code');if(!codeEl)return;var txt=codeEl.textContent||'';if(navigator.clipboard){navigator.clipboard.writeText(txt).then(function(){showToast('Fix copied!','success');});}else{fallbackCopy(txt);}}
function applyFilter(){
var groups=elements.issuesDiv?elements.issuesDiv.querySelectorAll('.issue-group'):[];
for(var gi=0;gi<groups.length;gi++){var rows=groups[gi].querySelectorAll('.issue-row');var visibleCount=0;
for(var ri=0;ri<rows.length;ri++){var row=rows[ri];var matchFilter=true;var matchSearch=true;
if(state.filter==='errors'){matchFilter=row.classList.contains('issue-error')||row.classList.contains('issue-critical');}
else if(state.filter==='warnings'){matchFilter=row.classList.contains('issue-warning');}
else if(state.filter==='info'){matchFilter=row.classList.contains('issue-info');}
else if(state.filter==='critical'){matchFilter=row.classList.contains('issue-critical');}
else if(state.filter==='seo'){matchFilter=!!row.querySelector('[data-category="seo"]')||row.classList.contains('issue-seo');}
else if(state.filter==='accessibility'){matchFilter=!!row.querySelector('[data-category="accessibility"]')||row.classList.contains('issue-a11y');}
else{matchFilter=true;}
if(state.search){var txt=row.textContent.toLowerCase();matchSearch=txt.indexOf(state.search)>=0;}
row.style.display=matchFilter&&matchSearch?'':'none';if(matchFilter&&matchSearch)visibleCount++;}
groups[gi].style.display=visibleCount===0?'none':'';}
if(elements.searchInput){var msgEl=document.getElementById('hv-filter-msg');if(!msgEl&&state.search){msgEl=document.createElement('div');msgEl.id='hv-filter-msg';msgEl.style.cssText='font-size:12px;color:#64748b;padding:4px 0;margin-top:-4px';if(elements.issuesDiv)elements.issuesDiv.insertBefore(msgEl,elements.issuesDiv.firstChild);}
if(msgEl){if(state.search){var total=0;for(var si=0;si<groups.length;si++){total+=groups[si].querySelectorAll('.issue-row[style*="display: none"]').length;msgEl.textContent='Search: "'+state.search+'" — '+total+' issues hidden';}if(state.search)msgEl.style.display='';else msgEl.style.display='none';}}}}
function reset(){if(elements.input)elements.input.value='';if(elements.summary)elements.summary.innerHTML='';if(elements.issuesDiv)elements.issuesDiv.innerHTML='';var ids=['hv-summary-text','hv-scores','hv-recommendations','hv-standards','hv-a11y-report','hv-seo-report'];for(var i=0;i<ids.length;i++){var el=document.getElementById(ids[i]);if(el){el.style.display='none';el.innerHTML='';}}state.results=null;state.history=[];state.filter='all';state.search='';if(elements.filterBar){var pb=elements.filterBar.querySelector('.hv-filter-btn.active');if(pb)pb.classList.remove('active');var fb=elements.filterBar.querySelector('[data-filter="all"]');if(fb)fb.classList.add('active');elements.filterBar.style.display='none';}if(elements.searchInput){elements.searchInput.value='';elements.searchInput.style.display='none';var fm=document.getElementById('hv-filter-msg');if(fm)fm.remove();}
if(elements.comparisonTable)elements.comparisonTable.innerHTML='';updateStatus('','');showEmptyState();if(elements.exportSection)elements.exportSection.style.display='none';if(elements.historySection)elements.historySection.style.display='none';if(elements.comparisonSection)elements.comparisonSection.style.display='none';}
function formatBytes(bytes){if(!bytes)return'0 B';if(bytes<1024)return bytes+' B';if(bytes<1048576)return(bytes/1024).toFixed(1)+' KB';return(bytes/1048576).toFixed(1)+' MB';}
function showToast(msg,type){var existing=document.querySelector('.toast');if(existing)existing.remove();var el=document.createElement('div');el.className='toast '+(type||'info');el.textContent=msg;document.body.appendChild(el);setTimeout(function(){el.classList.add('show');},10);setTimeout(function(){el.classList.remove('show');setTimeout(function(){el.remove();},300);},3000);}
